 private LinearLayout archiveList;
 private void loadArchive(){
  if(archiveList==null)return;archiveList.removeAllViews();
  if(android.os.Build.VERSION.SDK_INT<29){addArchiveMessage("La lista de archivos de Descargas requiere Android 10 o posterior.");return;}
  String[] columns={MediaStore.Files.FileColumns._ID,MediaStore.Files.FileColumns.DISPLAY_NAME,MediaStore.Files.FileColumns.MIME_TYPE,MediaStore.Files.FileColumns.DATE_MODIFIED,MediaStore.Files.FileColumns.RELATIVE_PATH};
  String selection=MediaStore.Files.FileColumns.RELATIVE_PATH+" LIKE ? AND ("+MediaStore.Files.FileColumns.DISPLAY_NAME+" LIKE ? OR "+MediaStore.Files.FileColumns.DISPLAY_NAME+" LIKE ? OR "+MediaStore.Files.FileColumns.DISPLAY_NAME+" LIKE ?)";
  String[] args={"%SubVoz%","%.srt","%.txt","%.mp3"};int found=0;
  try(Cursor c=getContentResolver().query(MediaStore.Files.getContentUri("external"),columns,selection,args,MediaStore.Files.FileColumns.DATE_MODIFIED+" DESC")){
   if(c!=null){int idCol=c.getColumnIndex(MediaStore.Files.FileColumns._ID),nameCol=c.getColumnIndex(MediaStore.Files.FileColumns.DISPLAY_NAME),mimeCol=c.getColumnIndex(MediaStore.Files.FileColumns.MIME_TYPE),dateCol=c.getColumnIndex(MediaStore.Files.FileColumns.DATE_MODIFIED),pathCol=c.getColumnIndex(MediaStore.Files.FileColumns.RELATIVE_PATH);
    while(c.moveToNext()){String name=c.getString(nameCol);if(name==null)continue;String low=name.toLowerCase(Locale.ROOT);if(!(low.endsWith(".srt")||low.endsWith(".txt")||low.endsWith(".mp3")))continue;String path=pathCol>=0?c.getString(pathCol):"";if(path==null||!path.toLowerCase(Locale.ROOT).contains("subvoz"))continue;
     long id=c.getLong(idCol);Uri uri=Uri.withAppendedPath(MediaStore.Files.getContentUri("external"),Long.toString(id));String mime=mimeCol>=0?c.getString(mimeCol):null;if(mime==null||mime.isEmpty())mime=low.endsWith(".mp3")?"audio/mpeg":"text/plain";long stamp=dateCol>=0?c.getLong(dateCol):0;addArchiveFile(name,path,stamp,uri,mime);found++;
    }
   }
  }catch(Exception e){addArchiveMessage("No se pudieron consultar las descargas. Revisa el permiso de archivos o vuelve a intentarlo.");return;}
  if(found==0)addArchiveMessage("Todavía no hay archivos SRT, TXT o MP3 en Descargas/SubVoz. Inicia una lectura y usa Guardar en la ventana flotante.");
 }
 private void addArchiveMessage(String message){TextView t=new TextView(this);t.setText(message);t.setTextColor(Color.rgb(89,101,121));t.setTextSize(14);t.setPadding(dp(16),dp(18),dp(16),dp(18));t.setBackground(round(Color.WHITE,16));archiveList.addView(t,fieldMargins());}
 private void addArchiveFile(String name,String path,long timestamp,Uri uri,String mime){
  LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(14),dp(13),dp(14),dp(12));card.setBackground(round(Color.WHITE,17));LinearLayout.LayoutParams cp=fieldMargins();archiveList.addView(card,cp);
  TextView title=new TextView(this);String ext=name.substring(name.lastIndexOf('.')+1).toUpperCase(Locale.ROOT);title.setText(ext+"   ·   "+name);title.setTextColor(NAVY);title.setTextSize(14);title.setTypeface(null,Typeface.BOLD);card.addView(title);
  String date=timestamp>0?android.text.format.DateFormat.getMediumDateFormat(this).format(new Date(timestamp*1000L))+" · "+android.text.format.DateFormat.getTimeFormat(this).format(new Date(timestamp*1000L)):"Fecha desconocida";
  TextView detail=new TextView(this);detail.setText(date+"\n"+path);detail.setTextColor(Color.rgb(104,105,117));detail.setTextSize(12);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,-2);dp.topMargin=dp(5);card.addView(detail,dp);
  LinearLayout actions=new LinearLayout(this);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,-2);ap.topMargin=dp(8);card.addView(actions,ap);Button open=button("Abrir",true);Button share=button("Compartir",false);actions.addView(open,new LinearLayout.LayoutParams(0,-2,1));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(0,-2,1);sp.leftMargin=dp(8);actions.addView(share,sp);
  open.setOnClickListener(v->{Intent view=new Intent(Intent.ACTION_VIEW);view.setDataAndType(uri,mime);view.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(view,"Abrir archivo"));}catch(Exception e){Toast.makeText(this,"No hay una aplicación para abrir este archivo.",Toast.LENGTH_LONG).show();}});
  share.setOnClickListener(v->{Intent send=new Intent(Intent.ACTION_SEND);send.setType(mime);send.putExtra(Intent.EXTRA_STREAM,uri);send.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(Intent.createChooser(send,"Compartir archivo"));}catch(Exception e){Toast.makeText(this,"No se pudo compartir el archivo.",Toast.LENGTH_LONG).show();}});
 }
 private class SimpleSelect implements AdapterView.OnItemSelectedListener{Runnable action;SimpleSelect(Runnable r){action=r;}public void onItemSelected(AdapterView<?> a,View v,int p,long id){action.run();}public void onNothingSelected(AdapterView<?> a){}}
 private void loadSpanishVoices(){if(tts.getVoices()!=null)for(Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals("es"))spanishVoices.add(v);Collections.sort(spanishVoices,(a,b)->a.getName().compareToIgnoreCase(b.getName()));ArrayList<String> names=new ArrayList<>();for(Voice v:spanishVoices)names.add(v.getName()+(v.isNetworkConnectionRequired()?" · en línea":" · sin conexión"));if(names.isEmpty())names.add("No hay voces españolas instaladas");voiceSpinner.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names));String saved=prefs.getString("voice","");for(int i=0;i<spanishVoices.size();i++)if(spanishVoices.get(i).getName().equals(saved)){voiceSpinner.setSelection(i);break;}}
 private void testVoice(){if(tts==null||spanishVoices.isEmpty()){new AlertDialog.Builder(this).setMessage("No se encontró una voz española. Instala una en Ajustes de Android → Síntesis de voz.").setPositiveButton("Abrir ajustes",(d,w)->startActivity(new Intent("com.android.settings.TTS_SETTINGS"))).setNegativeButton("Cerrar",null).show();return;}saveVoice();int selected=voiceSpinner.getSelectedItemPosition();if(selected>=0&&selected<spanishVoices.size())tts.setVoice(spanishVoices.get(selected));float rate=.55f+prefs.getInt("rate",50)/100f*1.05f;float pitch=.65f+prefs.getInt("pitch",50)/100f*.7f;tts.setSpeechRate(rate);tts.setPitch(pitch);tts.speak("Hola, esta es una prueba de voz de SubVoz.",TextToSpeech.QUEUE_FLUSH,null,"test");}
 private void applyVoiceProfile(int profile){
  int rate=50,pitch=50;
  if(profile==1){rate=39;pitch=47;} else if(profile==2){rate=65;pitch=57;} else if(profile==3){rate=43;pitch=34;} else if(profile==4){return;}
  applyingProfile=true;try{prefs.edit().putInt("rate",rate).putInt("pitch",pitch).apply();if(rateSeek!=null)rateSeek.setProgress(rate);if(pitchSeek!=null)pitchSeek.setProgress(pitch);}finally{applyingProfile=false;}
 }
 private void saveVoice(){int p=voiceSpinner.getSelectedItemPosition();if(p>=0&&p<spanishVoices.size())prefs.edit().putString("voice",spanishVoices.get(p).getName()).apply();}
 private void refreshAudioModelStatus(){if(audioModelStatus==null||audioLanguage==null)return;int ix=audioLanguage.getSelectedItemPosition();if(ix<0||ix>=OfflineSpeechModelStore.IDS.length)return;String id=OfflineSpeechModelStore.IDS[ix];boolean installed=OfflineSpeechModelStore.isInstalled(this,id);long[] sizes={38,48,48,41,31};audioModelStatus.setText((installed?"✓ Descargado · reconocimiento disponible sin conexión":"○ No descargado · descarga aproximada "+sizes[ix]+" MB")+"\nModelo: "+OfflineSpeechModelStore.NAMES[ix]);}
 private void downloadAudioModel(){int ix=audioLanguage.getSelectedItemPosition();String id=OfflineSpeechModelStore.IDS[ix];audioModelStatus.setText("Descargando "+OfflineSpeechModelStore.NAMES[ix]+"… 0%");OfflineSpeechModelStore.download(this,id,new OfflineSpeechModelStore.Progress(){public void update(int p){runOnUiThread(()->audioModelStatus.setText("Descargando "+OfflineSpeechModelStore.NAMES[ix]+"… "+p+"%"));}public void done(java.io.File f,Exception e){runOnUiThread(()->{audioModelStatus.setText(e==null?"✓ Descargado · reconocimiento disponible sin conexión":"No se pudo descargar el modelo. Revisa internet y espacio libre.");});}});}
 private void deleteAudioModel(){int ix=audioLanguage.getSelectedItemPosition();String id=OfflineSpeechModelStore.IDS[ix];if(!OfflineSpeechModelStore.isInstalled(this,id)){Toast.makeText(this,"Ese modelo ya no está descargado.",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Borrar modelo de audio").setMessage("Se eliminará el modelo local de "+OfflineSpeechModelStore.NAMES[ix]+". Tendrás que volver a descargarlo para reconocer ese idioma.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar",(d,w)->{OfflineSpeechModelStore.delete(this,id);refreshAudioModelStatus();}).show();}
 private void refreshModelStatus(){if(modelStatus==null||language==null)return;int source=language.getSelectedItemPosition();if(source<=0){modelStatus.setText("Español: no necesita modelo de traducción.");return;}modelStatus.setText("Consultando estado del modelo…");TranslateRemoteModel model=new TranslateRemoteModel.Builder(ML_LANG[source]).build();RemoteModelManager.getInstance().isModelDownloaded(model).addOnSuccessListener(ok->{if(modelStatus!=null)modelStatus.setText((ok?"✓ Descargado · disponible sin conexión":"○ No descargado · requiere internet la primera vez")+"\nIdioma: "+LANGUAGES[source]);}).addOnFailureListener(e->{if(modelStatus!=null)modelStatus.setText("No se pudo consultar el modelo. Revisa la conexión.");});}
 private void downloadSelectedModel(){int source=language.getSelectedItemPosition();if(source<=0){Toast.makeText(this,"Español no necesita traducción",Toast.LENGTH_SHORT).show();return;}modelStatus.setText("Descargando modelo de "+LANGUAGES[source]+"…");TranslateRemoteModel model=new TranslateRemoteModel.Builder(ML_LANG[source]).build();RemoteModelManager.getInstance().download(model,new DownloadConditions.Builder().build()).addOnSuccessListener(v->{modelStatus.setText("✓ Modelo descargado; podrás traducir sin conexión.");Toast.makeText(this,"Descarga completada",Toast.LENGTH_LONG).show();}).addOnFailureListener(e->{modelStatus.setText("No se pudo descargar. Comprueba internet e inténtalo de nuevo.");});}
 private void deleteSelectedModel(){int source=language.getSelectedItemPosition();if(source<=0){Toast.makeText(this,"No hay modelo de español que borrar",Toast.LENGTH_SHORT).show();return;}new AlertDialog.Builder(this).setTitle("Borrar modelo descargado").setMessage("Se eliminará el modelo de "+LANGUAGES[source]+". Para volver a traducir ese idioma tendrás que descargarlo otra vez.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar",(d,w)->{TranslateRemoteModel model=new TranslateRemoteModel.Builder(ML_LANG[source]).build();RemoteModelManager.getInstance().deleteDownloadedModel(model).addOnSuccessListener(v->refreshModelStatus()).addOnFailureListener(e->modelStatus.setText("No se pudo borrar el modelo."));}).show();}
 private SeekBar addSeek(LinearLayout root,String title,int min,int max,int progress,java.util.function.IntConsumer changed){TextView label=smallLabel(title);root.addView(label);SeekBar s=new SeekBar(this);s.setMax(max-min);s.setProgress(Math.max(0,Math.min(max-min,progress-min)));root.addView(s,fieldMargins());TextView value=smallLabel("");root.addView(value);if(title.equals("Velocidad"))rateValue=value;else if(title.equals("Tono"))pitchValue=value;else sizeValue=value;changed.accept(s.getProgress()+min);s.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){changed.accept(p+min);if(user&&!applyingProfile&&speechStyleSpinner!=null&&(title.equals("Velocidad")||title.equals("Tono")))speechStyleSpinner.setSelection(4);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});return s;}
 private void sectionTitle(LinearLayout root,String title,String subtitle){TextView t=new TextView(this);t.setText(title);t.setTextColor(NAVY);t.setTextSize(20);t.setTypeface(null,Typeface.BOLD);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(23);root.addView(t,p);TextView s=new TextView(this);s.setText(subtitle);s.setTextColor(Color.rgb(89,101,121));s.setTextSize(14);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(-1,-2);q.topMargin=dp(4);q.bottomMargin=dp(10);root.addView(s,q);}
 private TextView smallLabel(String value){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.rgb(52,64,86));t.setTextSize(14);t.setTypeface(null,Typeface.BOLD);return t;}
 private void styleSpinner(Spinner s){s.setPadding(dp(10),dp(8),dp(10),dp(8));s.setBackground(round(Color.WHITE,13));}
 private Button button(String text,boolean primary){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(14);b.setTypeface(null,Typeface.BOLD);b.setTextColor(primary?Color.WHITE:NAVY);b.setBackground(round(primary?NAVY:Color.rgb(255,255,255),15));return b;}
 private GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout.LayoutParams fieldMargins(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);return p;}
 private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
 private void confirmCapture(){boolean audio=modeSpinner.getSelectedItemPosition()==1;String title=audio?"Permitir captura de audio interno":"Permitir captura de pantalla";String details=audio?"Android solicitará permiso de audio y su confirmación para compartir pantalla/audio. SubVoz procesa los píxeles visibles para OCR y captura el audio reproducido solo durante esta sesión; no usa el micrófono ni guarda o sube audio/vídeo desde SubVoz. Algunos reproductores, Android o DRM pueden bloquear la captura.":"Android mostrará su confirmación para compartir la pantalla. SubVoz procesa los píxeles visibles para leer subtítulos; no guarda ni sube vídeo ni capturas. Android, algunas apps o DRM pueden bloquear la captura.";new AlertDialog.Builder(this).setTitle(title).setMessage(details).setNegativeButton("Cancelar",null).setPositiveButton("Continuar",(d,w)->{if(audio&&checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},124);else beginProjection();}).show();}
 private void beginProjection(){if(!Settings.canDrawOverlays(this)){Toast.makeText(this,"Activa primero el permiso de ventana flotante",Toast.LENGTH_LONG).show();return;}MediaProjectionManager m=(MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE);startActivityForResult(m.createScreenCaptureIntent(),123);}
 @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==124){if(results.length>0&&results[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)beginProjection();else Toast.makeText(this,"Sin permiso de audio no se puede capturar la reproducción.",Toast.LENGTH_LONG).show();}}
 @Override protected void onPause(){super.onPause();if(modeSpinner!=null)prefs.edit().putInt("mode",modeSpinner.getSelectedItemPosition()).apply();if(language!=null&&language.getSelectedItemPosition()>=0)prefs.edit().putInt("source",language.getSelectedItemPosition()).apply();if(audioLanguage!=null&&audioLanguage.getSelectedItemPosition()>=0)prefs.edit().putInt("audioLang",audioLanguage.getSelectedItemPosition()).apply();if(region!=null&&region.getSelectedItemPosition()>=0)prefs.edit().putInt("region",region.getSelectedItemPosition()).apply();if(outputSpinner!=null)prefs.edit().putInt("outputMode",outputSpinner.getSelectedItemPosition()).apply();if(voiceSpinner!=null)saveVoice();if(speechStyleSpinner!=null)prefs.edit().putInt("voiceStyle",speechStyleSpinner.getSelectedItemPosition()).apply();if(styleSpinner!=null)prefs.edit().putInt("style",styleSpinner.getSelectedItemPosition()).apply();}
 @Override protected void onDestroy(){if(tts!=null){tts.stop();tts.shutdown();}super.onDestroy();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==123&&result==RESULT_OK&&data!=null){saveVoice();Intent i=new Intent(this,CaptureService.class);i.putExtra("code",result);i.putExtra("data",data);i.putExtra("source",language.getSelectedItemPosition());i.putExtra("audioLang",audioLanguage.getSelectedItemPosition());i.putExtra("region",region.getSelectedItemPosition());i.putExtra("zone",prefs.getInt("zone",30));i.putExtra("style",styleSpinner.getSelectedItemPosition());i.putExtra("textSize",prefs.getInt("textSize",16));i.putExtra("rate",prefs.getInt("rate",50));i.putExtra("pitch",prefs.getInt("pitch",50));i.putExtra("voiceStyle",prefs.getInt("voiceStyle",4));i.putExtra("voice",prefs.getString("voice",""));i.putExtra("mode",modeSpinner.getSelectedItemPosition());i.putExtra("translateSubtitles",outputSpinner.getSelectedItemPosition()==0);startForegroundService(i);}}
